npm ci --no-audit --no-fund >/dev/null 2>&1; npx vite build 2>&1 | tail -25; echo ---; cd dist; echo "JS/CSS (bytes, gzip):"; for f in assets/*.js assets/*.css; do printf "%s %s %s\n" "$(stat -c%s $f)" "$(gzip -c $f | wc -c)" "$f"; done | sort -rn | head -12; echo "--- datos"; find data -name "*.json" -printf "%s %p\n" | sort -rn | head -12; echo "--- total dist (sin audio/imagenes):"; du -sk . ; du -sk images data assets 2>/dev/null; echo "--- precache entries:"; grep -o "\"url\"" sw.js | wc -l; ls -la sw.js; find . -name "*.pmtiles" -printf "%s %p\n"; find images -type f -printf "%s\n" | sort -rn | head -3
